import{B,C,read,circle}from'../ten-utils.js';
export default({g,p,extra,t})=>{let mode=extra.mode??0;if(mode===0){let n=p[0],dx=Math.min(.45,2.1/Math.max(1,n-1));for(let i=0;i<n;i++){let x=(i-(n-1)/2)*dx,y=(i%2)*.18;g.sphere(x,y,0,.12,C.dark,'C');if(i)g.line([x-dx,(1-i%2)*.18,0],[x,y,0],C.white,3);for(let j=0;j<(n===1?4:i===0||i===n-1?3:2);j++){let a=j*Math.PI*2/(n===1?4:3);let h=[x+.23*Math.cos(a),y+.23*Math.sin(a),j%2?.17:-.17];g.line([x,y,0],h);g.sphere(...h,.045,C.white)}}g.text(0,-.9,0,`${n===1?'C':'C'+n}H${2*n+2}`);return[read('Carbon atoms','कार्बन परमाणु',n),read('Hydrogen atoms','हाइड्रोजन परमाणु',2*n+2),read('Successive members differ by','अगली सदस्य इकाई का अंतर','CH2')]}
 if(mode===1){let order=p[0],H=6-2*(order-1);g.sphere(-.45,0,0,.18,C.dark,'C');g.sphere(.45,0,0,.18,C.dark,'C');for(let j=0;j<order;j++){let y=(j-(order-1)/2)*.09;g.line([-.3,y,0],[.3,y,0],C.gold,3)}for(let s of[-1,1])for(let i=0;i<H/2;i++){let a=(i-(H/2-1)/2)*.8,y=.4*Math.sin(a),x=s*(.45+.35*Math.cos(a));g.line([s*.45,0,0],[x,y,0]);g.sphere(x,y,0,.06,C.white,'H')}return[read('Carbon–carbon bond order','कार्बन–कार्बन बंध क्रम',order),read('Formula','सूत्र',`C2H${H}`),read('Shared electron pairs between C atoms','C परमाणुओं में साझा इलेक्ट्रॉन युग्म',order)]}
 let hard=p[0];g.sphere(0,0,0,.35,'#c68960',B('Grease','चिकनाई'));for(let i=0;i<18;i++){let a=i*Math.PI*2/18,r=.65;g.line([.34*Math.cos(a),.34*Math.sin(a),0],[r*Math.cos(a),r*Math.sin(a),0],C.gold,2);g.sphere(r*Math.cos(a),r*Math.sin(a),0,.055,i<hard?C.dark:C.blue)}for(let i=0;i<hard;i++)g.sphere(-1+i*.2,.95,0,.07,C.pink);return[read('Hydrophilic heads face','जलरागी सिर किस ओर',B('Water','जल')),read('Hydrophobic tails face','जलविरागी पूँछ किस ओर',B('Grease','चिकनाई')),read('Hard-water effect','कठोर जल का प्रभाव',hard>0?B('More insoluble scum; less available soap','अधिक अघुलनशील मैल; कम उपलब्ध साबुन'):B('No added hard-water ions','कठोर जल के अतिरिक्त आयन नहीं'))]};
